package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.repositories.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/stats") public class StatsController{private final DepartmentRepository d;private final DoctorRepository dr;private final PatientRepository p;public StatsController(DepartmentRepository d,DoctorRepository dr,PatientRepository p){this.d=d;this.dr=dr;this.p=p;}@GetMapping("/hospital/{id}") public Map<String,Long> hospital(@PathVariable Long id){return Map.of("departments",d.countByHospitalIdAndIsActiveTrue(id),"doctors",dr.countByHospitalIdAndIsActiveTrue(id),"patients",p.countByHospitalIdAndIsActiveTrue(id));}}
